 "content": "from collections import Counter, deque


def _norm(shape):
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    return frozenset((r - min_r, c - min_c) for r, c in shape)


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The object panel is separated from the framed panels by a blank column.
    left_w = next((c for c in range(w) if all(grid[r][c] == 0 for r in range(h))), w)
    left = [row[:left_w] for row in grid]
    frame_color = Counter(v for row in left for v in row if v != 0).most_common(1)[0][0]

    # Collect each colored object on the right and index it by its normalized shape.
    seen = set()
    shape_color = {}
    for r in range(h):
        for c in range(left_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and left_w <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            shape_color[_norm(cells)] = color

    # Full-width frame rows delimit panels. Match each panel's zero silhouette
    # to the congruent colored object and fill its holes with that object's color.
    delimiter_rows = [r for r, row in enumerate(left)
                      if row and all(v == frame_color for v in row)]
    out = [row[:] for row in left]
    for top, bottom in zip(delimiter_rows, delimiter_rows[1:]):
        holes = [(r - top - 1, c) for r in range(top + 1, bottom)
                 for c, value in enumerate(left[r]) if value != frame_color]
        if not holes:
            continue
        color = shape_color[_norm(holes)]
        for r in range(top + 1, bottom):
            for c, value in enumerate(left[r]):
                if value != frame_color:
                    out[r][c] = color
    return out


